//go:wasmimport golem:api/oplog@1.5.0 [resource-drop]get-oplog
func resourceDropGetOplog(handle int32)

type GetOplog struct {
	handle *witRuntime.Handle
}

func (self *GetOplog) TakeHandle() int32 {
	return self.handle.Take()
}

func (self *GetOplog) SetHandle(handle int32) {
	self.handle.Set(handle)
}

func (self *GetOplog) Handle() int32 {
	return self.handle.Use()
}

func (self *GetOplog) Drop() {
	handle := self.handle.TakeOrNil()
	if handle != 0 {
		resourceDropGetOplog(handle)
	}
}

func GetOplogFromOwnHandle(handleValue int32) *GetOplog {
	handle := witRuntime.MakeHandle(handleValue)
	value := &GetOplog{handle}
	runtime.AddCleanup(value, func(_ int) {
		handleValue := handle.TakeOrNil()
		if handleValue != 0 {
			resourceDropGetOplog(handleValue)
		}
	}, 0)
	return value
}

func GetOplogFromBorrowHandle(handleValue int32) *GetOplog {
	handle := witRuntime.MakeHandle(handleValue)
	return &GetOplog{handle}
}

